    scene.world().setKineticSpeed(pistonTe, 16.0f);
    scene.world().moveSection(piston, util.vector().of(0.0, 0.0, 1.0), 40);
    scene.world().moveSection(cannon, util.vector().of(0.0, 0.0, 1.0), 40);
