package rbasamoyai.createbigcannons.ponder;

import com.simibubi.create.foundation.ponder.CreateSceneBuilder;
import net.createmod.ponder.api.PonderPalette;
import net.createmod.ponder.api.element.ElementLink;
import net.createmod.ponder.api.scene.SceneBuilder;
import net.createmod.ponder.api.scene.SceneBuildingUtil;
import net.createmod.ponder.api.scene.Selection;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;

public class CannonKineticsScenes {
    public static void slidingBreech(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("cannon_mount/sliding_breech", "Using a Sliding Breech");
        scene.configureBasePlate(0, 0, 5);
        scene.showBasePlate();
        BlockPos breechPos = util.grid().at(2, 1, 2);
        scene.world().showSection(util.select().fromTo(breechPos, util.grid().at(2, 1, 4)), Direction.DOWN);
        scene.idle(20);
        scene.overlay().showText(80).text("Sliding Breeches offer a quick way to load cannons from the breech, at the cost of cannon strength.").pointAt(util.vector().centerOf(breechPos));
        scene.idle(100);
        scene.world().showSection(util.select().fromTo(3, 1, 2, 3, 2, 3), Direction.WEST);
        scene.world().showSection(util.select().position(2, 2, 3), Direction.WEST);
        scene.idle(30);
        scene.addKeyframe();
        Selection gearUp = util.select().fromTo(2, 2, 3, 3, 2, 3);
        Selection gearDown = util.select().fromTo(breechPos, util.grid().at(3, 1, 2));
        scene.world().setKineticSpeed(gearUp, -16.0f);
        scene.world().setKineticSpeed(gearDown, 8.0f);
        scene.idle(40);
        scene.overlay().showText(60).text("Use rotational force to open up sliding breeches.").pointAt(util.vector().centerOf(breechPos));
        scene.idle(40);
        scene.world().setKineticSpeed(gearUp, 0.0f);
        scene.world().setKineticSpeed(gearDown, 0.0f);
        scene.idle(20);
        scene.addKeyframe();
        BlockPos munitionPos = util.grid().at(2, 1, 1);
        ElementLink munitionBlock = scene.world().showIndependentSection(util.select().position(munitionPos), Direction.SOUTH);
        scene.idle(15);
        scene.overlay().showText(80).text("Once the sliding breech is fully opened, cannon munitions can be loaded through the breech.").pointAt(util.vector().centerOf(munitionPos)).colored(PonderPalette.GREEN);
        scene.idle(15);
        scene.world().moveSection(munitionBlock, util.vector().of(0.0, 0.0, 2.0), 40);
        scene.idle(80);
        scene.addKeyframe();
        scene.world().setKineticSpeed(gearUp, 16.0f);
        scene.world().setKineticSpeed(gearDown, -8.0f);
        scene.idle(40);

