private static void animateQFBHack(SceneBuilder scene, Selection breechSel, boolean close) {
    int i = 0;
    while (i < 5) {
        int finalI = i++;
        scene.world().modifyBlockEntityNBT(breechSel, QuickfiringBreechBlockEntity.class, compoundTag -> {
            compoundTag.m_128405_("OpenDirection", close ? -1 : 1);
            compoundTag.m_128405_("OpenProgress", close ? 5 - finalI : finalI);
        });
        scene.idle(1);
    }
    scene.world().modifyBlockEntityNBT(breechSel, QuickfiringBreechBlockEntity.class, compoundTag -> {
        compoundTag.m_128405_("OpenDirection", 0);
        compoundTag.m_128405_("OpenProgress", close ? 0 : 5);
    });
}

