        scene.showBasePlate();
        Selection cannonMount = util.select().position(2, 3, 2);
        ArrayList<ElementLink> setupBlocks = new ArrayList<ElementLink>();
        Vec3 down = util.vector().of(0.0, -1.0, 0.0);
        scene.world().modifyBlockEntityNBT(cannonMount, CannonMountBlockEntity.class, tag -> {
            tag.m_128350_("CannonYaw", Direction.WEST.m_122435_());
