            scene.idle(5);
            cannonPlacement.add(block);
        }
        scene.idle(20);
        scene.overlay().showText(80).attachKeyFrame().text("Big cannons need to be placed on cannon mounts to be assembled.").pointAt(util.vector().blockSurface(util.grid().at(2, 2, 2), Direction.NORTH));
        scene.idle(90);
        scene.overlay().showText(80).attachKeyFrame().text("To assemble a cannon, power the hammer face with a redstone signal.").pointAt(util.vector().blockSurface(util.grid().at(2, 2, 2), Direction.WEST));
        scene.idle(90);
        BlockPos leverPos = util.grid().at(1, 3, 2);
        ElementLink lever = scene.world().showIndependentSectionImmediately(util.select().position(leverPos));
        scene.world().moveSection(lever, down, 0);
        scene.idle(15);
        setupBlocks.add(lever);
